(function(){
  const track = document.getElementById('heroPhotoTrack');
  const dots = Array.from(document.querySelectorAll('#heroPhotoDots .hero-photo-dot'));
  const prev = document.getElementById('heroPhotoPrev');
  const next = document.getElementById('heroPhotoNext');
  const video = document.getElementById('heroVideo');
  if(!track || !dots.length) return;
  let index = 0;
  let timer;
  const total = dots.length;
  function render(){
    track.style.transform = `translate3d(-${index * 100}%,0,0)`;
    dots.forEach((dot,i)=>dot.classList.toggle('active',i===index));
  }
  function go(step){ index=(index+step+total)%total; render(); }
  function restart(){ clearInterval(timer); timer=setInterval(()=>go(1),4500); }
  dots.forEach((dot,i)=>dot.addEventListener('click',()=>{index=i;render();restart();}));
  prev?.addEventListener('click',()=>{go(-1);restart();});
  next?.addEventListener('click',()=>{go(1);restart();});
  const card=document.querySelector('.hero-photo-carousel');
  let startX=0;
  card?.addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX;},{passive:true});
  card?.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-startX;if(Math.abs(dx)>40){go(dx<0?1:-1);restart();}},{passive:true});
  if(video){
    video.addEventListener('error',()=>{video.style.display='none';});
    const play=()=>video.play().catch(()=>{});
    document.addEventListener('visibilitychange',()=>{if(document.hidden) video.pause(); else play();});
    play();
  }
  render();
  restart();
})();

/* =========================================================
   FAQ ACCORDION
   ========================================================= */

window.toggleFaq = function (button) {

  if (!button) return;

  const item = button.closest(".faq-item");

  if (!item) return;

  const isOpen =
    item.classList.contains("open");


  /*
   * Close all other FAQ items
   * so only one remains open.
   */

  document
    .querySelectorAll(".faq-item.open")
    .forEach(function (openItem) {

      if (openItem !== item) {
        openItem.classList.remove("open");
      }

    });


  /*
   * Toggle current item.
   */

  item.classList.toggle("open");

};


/* Delivery Popup */

/* =========================================================
   DELIVERY TERMS MODAL
   ========================================================= */

function openDeliveryTerms() {
  const modal = document.getElementById(
    "deliveryTermsModal"
  );

  if (!modal) return;

  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");

  document.body.style.overflow = "hidden";
}


function closeDeliveryTerms() {
  const modal = document.getElementById(
    "deliveryTermsModal"
  );

  if (!modal) return;

  modal.classList.remove("open");
  modal.setAttribute("aria-hidden", "true");

  document.body.style.overflow = "";
}


/* Close when clicking outside the popup */
document.addEventListener("click", function (event) {

  const modal =
    document.getElementById("deliveryTermsModal");

  if (
    modal &&
    event.target === modal
  ) {
    closeDeliveryTerms();
  }

});


/* Close with Escape */
document.addEventListener("keydown", function (event) {

  if (event.key !== "Escape") return;

  const modal =
    document.getElementById("deliveryTermsModal");

  if (
    modal &&
    modal.classList.contains("open")
  ) {
    closeDeliveryTerms();
  }

});

