(function () {
    "use strict";

    const trigger = document.getElementById("menu-search-trigger");
    const view = document.getElementById("menu-search-view");
    const input = document.getElementById("menu-search-input");
    const back = document.getElementById("menu-search-back");
    const clear = document.getElementById("menu-search-clear");

    if (!trigger || !view || !input) return;

    function openMenuSearch() {
      view.classList.add("open");
      view.setAttribute("aria-hidden", "false");
      document.body.classList.add("menu-search-open");

      requestAnimationFrame(function () {
        input.focus();
      });
    }

    function closeMenuSearch() {
      view.classList.remove("open");
      view.setAttribute("aria-hidden", "true");
      document.body.classList.remove("menu-search-open");

      if (document.activeElement === input) input.blur();
    }

    trigger.addEventListener("click", openMenuSearch);

    if (back) back.addEventListener("click", closeMenuSearch);

    if (clear) {
      clear.addEventListener("click", function () {
        input.value = "";
        input.dispatchEvent(new Event("input", { bubbles: true }));
        input.focus();
      });
    }

    document.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && view.classList.contains("open")) {
        closeMenuSearch();
      }
    });

    if (window.location.hash === "#search") {
      openMenuSearch();
    }
  })();

(function () {
  "use strict";

  function syncHeaderHeight() {
    var header = document.querySelector("body > header, header");
    if (!header) return;

    var height = Math.ceil(header.getBoundingClientRect().height);
    document.documentElement.style.setProperty(
      "--probow-header-height",
      height + "px"
    );
  }

  function init() {
    syncHeaderHeight();

    var header = document.querySelector("body > header, header");

    if (header && "ResizeObserver" in window) {
      new ResizeObserver(syncHeaderHeight).observe(header);
    }

    window.addEventListener("resize", syncHeaderHeight, { passive: true });
    window.addEventListener("orientationchange", syncHeaderHeight, { passive: true });

    if (window.visualViewport) {
      window.visualViewport.addEventListener("resize", syncHeaderHeight, { passive: true });
    }

    /*
     * The hamburger/navigation can change header dimensions after
     * a click, so re-measure after interaction as well.
     */
    document.addEventListener("click", function () {
      window.setTimeout(syncHeaderHeight, 50);
      window.setTimeout(syncHeaderHeight, 250);
    }, { passive: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

